#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int maximumScore(int* nums, int numsSize, int k) {
    int left = k, right = k;
    int currentMin = nums[k];
    long long ans = currentMin;

    while (left > 0 || right < numsSize - 1) {
        if (left == 0) {
            right++;
        } else if (right == numsSize - 1) {
            left--;
        } else if (nums[left - 1] >= nums[right + 1]) {
            left--;
        } else {
            right++;
        }

        if (nums[left] < currentMin) currentMin = nums[left];
        if (nums[right] < currentMin) currentMin = nums[right];

        long long score = (long long)currentMin * (right - left + 1);
        if (score > ans) ans = score;
    }

    return (int)ans;
}

static int* parseInts(const char* line, int* count) {
    int capacity = 128;
    int size = 0;
    int* values = (int*)malloc((size_t)capacity * sizeof(int));
    if (!values) return NULL;

    const char* p = line;
    while (*p) {
        while (*p && !isdigit((unsigned char)*p) && *p != '-') p++;
        if (!*p) break;

        int sign = 1;
        if (*p == '-') {
            sign = -1;
            p++;
        }

        int value = 0;
        while (*p && isdigit((unsigned char)*p)) {
            value = value * 10 + (*p - '0');
            p++;
        }

        if (size == capacity) {
            capacity *= 2;
            int* tmp = (int*)realloc(values, (size_t)capacity * sizeof(int));
            if (!tmp) {
                free(values);
                return NULL;
            }
            values = tmp;
        }
        values[size++] = sign * value;
    }

    *count = size;
    return values;
}

